            Label {
                Layout.fillWidth: true
                visible: poseBridge.rowCount === 0
                color: Theme.fgDim
                wrapMode: Text.Wrap
                text: qsTr("No frames loaded — load a study first.")
            }
            Label {
                Layout.fillWidth: true
                visible: poseBridge.rowCount > 0
                         && studyBridge.primaryModelIndex < 0
                color: Theme.fgDim
