                        }
                    }
                }
                Button {
                    text: qsTr("Models")
                    enabled: !optimizerBridge.running
                    onClicked: {
                        if (!studyBridge.hasCalibration) {
                            showMessage(qsTr("Error!"),
                                        qsTr("Load Calibration First!"))
                        } else {
